// The compound set for combine mode (ADR 20), generated by `npm run data:compounds`.
// Import it only from combine's lazy chunk, so visitors who never open Combine skip it.
import data from '../../data/compounds.json' with { type: 'json' };
import { fromColumns, type Columns } from '../columns.ts';
import type { Compound } from './normalize.ts';

// Runtime values come from the zod-free source module; normalize.ts gives types only, so zod
// stays out of the app bundle, as with the elements.
export type { Compound } from './normalize.ts';
export { CARRY_LIMIT, CONTEXTS, type Bond, type CompoundKind, type Context } from './source.ts';

/** The set in everyday order, stored by column (`core/columns.ts`). */
export const COMPOUNDS = fromColumns(data as Columns<Compound>);
